package io.github.diodeme.ji.telemetry;

import java.util.Objects;
import java.util.Optional;

/** Opaque adapter-owned parent token; never persisted as application state. */
public record SpanParent(Optional<Object> nativeContext) {
    private static final SpanParent ROOT = new SpanParent(Optional.empty());

    public SpanParent {
        nativeContext = Objects.requireNonNull(nativeContext, "nativeContext");
    }

    public static SpanParent root() {
        return ROOT;
    }

    public static SpanParent of(Object nativeContext) {
        return new SpanParent(Optional.of(nativeContext));
    }
}
